package io.github.diodeme.ji.acp.v1;

import java.io.FilterInputStream;
import java.io.IOException;
import java.io.InputStream;

/** Test transport that exposes arbitrary one-byte fragmentation to the official stdio decoder. */
final class FragmentingInputStream extends FilterInputStream {
    FragmentingInputStream(InputStream input) { super(input); }

    @Override
    public int read(byte[] bytes, int offset, int length) throws IOException {
        return super.read(bytes, offset, Math.min(1, length));
    }
}
